def number_to_words(n: int) -> str:
    if not (0 <= n <= 999999):
        raise ValueError("n must be between 0 and 999999")

    ones = ["zero", "one", "two", "three", "four", "five", "six", "seven",
            "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
            "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
            "eighty", "ninety"]

    def three_digit_to_words(num: int) -> str:
        # num is between 0 and 999
        parts = []
        hundreds_digit = num // 100
        remainder = num % 100
        if hundreds_digit > 0:
            parts.append(ones[hundreds_digit] + " hundred")
        if remainder > 0:
            if remainder < 20:
                parts.append(ones[remainder])
            else:
                tens_digit = remainder // 10
                units_digit = remainder % 10
                if units_digit > 0:
                    parts.append(tens[tens_digit] + "-" + ones[units_digit])
                else:
                    parts.append(tens[tens_digit])
        return " ".join(parts)

    if n == 0:
        return "zero"

    if n < 1000:
        return three_digit_to_words(n)

    thousands_part = n // 1000
    remainder_part = n % 1000

    words = []
    words.append(three_digit_to_words(thousands_part) + " thousand")
    if remainder_part > 0:
        words.append(three_digit_to_words(remainder_part))

    return " ".join(words)
